el('launch').onclick=()=>{tv=window.open('','leagueFinalTV','popup,width=1080,height=608');if("'!tv){el('"'status').textContent='Allow pop-ups for this file, then open the TV window again.';return}tv.document.open();tv.document.write('<"'!doctype html><html lang="en"><meta charset="utf-8"><title>League bowling • Final night</title><style>'"'+el('styles').textContent+'</style><body class=\"screen\"><div class=\"stage\">'+slide+'</div></body></html>');tv.document.close();tv.document.ondblclick=()=>{if("'!tv.document.fullscreenElement)tv.document.documentElement.requestFullscreen?.().catch(()=>{})};el('"'status').textContent='TV window open'};
setInterval(()=>{if(tv&&tv.closed){tv=null;el('status').textContent='TV window closed'}},1000);
awards.forEach((name,i)=>{const box=document.createElement('div');box.className='card';box.innerHTML='<h3>'+name+'</h3><label>Winner<input maxlength=\"48\" placeholder=\"Name or team\"></label><label>'+['Score','Average gain','Detail'][i]+' (optional)<input maxlength=\"40\" placeholder=\"'+['e.g. 214 pins','e.g. +18 pins','e.g. fan favorite'][i]+'\"></label><button>Reveal award</button>';el('awards').append(box);const inputs=box.querySelectorAll('input'),btn=box.querySelector('button');btn.setAttribute('aria-label','Reveal '+name);inputs.forEach((input,j)=>{input.value=drafts[i][j];input.oninput=()=>{drafts[i][j]=input.value;btn.disabled="'!inputs[0].value.trim();try{localStorage.setItem('"'six-team-final-drafts',JSON.stringify(drafts));el('save').textContent='Drafts saved in this browser.'}catch{el('save').textContent='Keep this desk open to retain your drafts.'}}});btn.disabled="'!inputs[0].value.trim();btn.onclick=()=>render(name,inputs[0].value.trim(),inputs[1].value.trim(),false,true)});
</script></html>
EOF'

